/*
 * A383422  The infinite Lucas word; the limiting word generated by s(0) = 0,
 *          s(1) = 011, and s(n) = s(n-1)s(n-2).
 * https://oeis.org/A383422
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn
 * Formula:   a(n) is the nth term of the infinite Lucas word obtained from
 *            s(0)=0, s(1)=011 and s(k)=s(k-1)s(k-2). The value is calculated
 *            by successive decomposition of n according to the lengths of the
 *            concatenated blocks (Lucas numbers)
 * Range:     u8 n <= 85, u16 n <= 85, u32 n <= 85, u64 n <= 85, u128 n <= 85,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* Compute Lucas-lengths L(k)=L(k-1)+L(k-2) until L(k)>n.
       The array size 128 is more than enough for 64‑bit n (≈93 terms). */
    seq_t lengths[128];
    lengths[0] = 1;        /* length of s(0) */
    lengths[1] = 3;        /* length of s(1) */
    unsigned int i = 1;
    while (lengths[i] <= (seq_t)n) {
        ++i;
        lengths[i] = lengths[i-1] + lengths[i-2];
    }
    unsigned int k = i;        /* first index with lengths[k] > n */
    idx_t idx = n;

    /* Walk down the decomposition tree */
    while (k > 1) {
        if ((seq_t)idx < lengths[k-1]) {
            --k;                     /* go into the left child */
        } else {
            idx -= (idx_t)lengths[k-1];  /* subtract left block length */
            k -= 2;                     /* go into the right child */
        }
    }

    /* Base cases */
    if (k == 0) {
        return (seq_t)0;
    } else { /* k == 1 */
        return (idx == 0) ? (seq_t)0 : (seq_t)1;
    }
}
